	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		ProductionSchedule
	 */
		public ProductionSchedule createProductionSchedule( CreateProductionScheduleCommand command ) {

		ProductionSchedule entity = new ProductionSchedule();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setProductionScheduleId( command.getProductionScheduleId() );
            entity.setScheduleNumber( command.getScheduleNumber() );
            entity.setHorizonStart( command.getHorizonStart() );
            entity.setHorizonEnd( command.getHorizonEnd() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of ProductionSchedule {0} ", entity.toString() );

		return entity;
	}

